window.QB_TWK_B13 = [
{id:"TWK-2001",q:"Nilai yang terkandung dalam sila pertama Pancasila adalah ....",opts:["ketakwaan terhadap Tuhan Yang Maha Esa","persamaan derajat sesama manusia","persatuan dan kesatuan bangsa","kedaulatan rakyat","keadilan sosial"],a:0,ex:"Sila pertama bernilai ketakwaan/religiusitas; persamaan derajat = sila 2, persatuan = sila 3, kedaulatan rakyat = sila 4, keadilan = sila 5."},
{id:"TWK-2002",q:"Sidang kedua BPUPKI dilaksanakan pada tanggal ....",opts:["10-17 Juli 1945","29 Mei-1 Juni 1945","22 Juni 1945","18 Agustus 1945","29 April 1945"],a:0,ex:"Sidang II BPUPKI 10-17 Juli 1945 membahas rancangan UUD; sidang I 29 Mei-1 Juni membahas dasar negara; 22 Juni Piagam Jakarta."},
{id:"TWK-2003",q:"Ketua Panitia Perancang Undang-Undang Dasar sidang kedua BPUPKI adalah ....",opts:["Ir. Soekarno","Drs. Mohammad Hatta","Mr. Soepomo","Mr. Muhammad Yamin","Dr. Radjiman Wedyodiningrat"],a:0,ex:"Panitia Perancang UUD diketuai Soekarno; Panitia Ekonomi-Keuangan oleh Hatta, Panitia Pembela Tanah Air oleh Soetardjo."},
{id:"TWK-2004",q:"Berikut ini yang termasuk anggota Panitia Sembilan perumus Piagam Jakarta adalah ....",opts:["Ki Bagus Hadikusumo","Mr. Soepomo","Mr. Sartono","R.M. Soeripto","Mr. Wongsonegoro"],a:0,ex:"Panitia Sembilan: Soekarno, Hatta, Yamin, Soebarjo, Maramis, Muzakkir, Wahid Hasyim, Kahar Muzakir, Agus Salim, Abikusno... Ki Bagus Hadikusumo (Muhammadiyah) termasuk; Soepomo tidak."},
{id:"TWK-2005",q:"Makna 'hikmat kebijaksanaan' dalam sila keempat Pancasila adalah ....",opts:["menggunakan akal sehat dan pertimbangan matang dalam bermusyawarah","kepandaian seseorang dalam berpidato","kebijaksanaan seorang pemimpin yang mutlak","ilmu pengetahuan yang tinggi","pengalaman hidup yang panjang"],a:0,ex:"Hikmat kebijaksanaan = akal sehat dan nalar dalam musyawarah; bukan kepandaian pidato, kekuasaan mutlak pemimpin, atau sekadar pengalaman."},
{id:"TWK-2006",q:"Pancasila sebagai perjanjian luhur bangsa Indonesia berarti ....",opts:["disepakati bersama oleh para pendiri bangsa sebagai dasar negara","hanya disetujui oleh golongan tertentu","merupakan hasil paksaan penjajah","disusun tanpa melalui musyawarah","berlaku sementara waktu saja"],a:0,ex:"Pancasila adalah perjanjian luhur (modus vivendi) yang disepakati para pendiri bangsa; bukan paksaan, bukan sementara, dan disusun lewat musyawarah."},
{id:"TWK-2007",q:"Perbedaan Pancasila dengan ideologi liberalisme terletak pada ....",opts:["Pancasila menekankan keseimbangan hak individu dan kewajiban sosial","Pancasila menolak seluruh kebebasan individu","liberalisme mengutamakan kepentingan kolektif","keduanya sama-sama menolak agama","Pancasila tidak mengakui hak asasi manusia"],a:0,ex:"Pancasila seimbang antara individu dan kolektif; liberalisme mengutamakan individu, komunisme kolektif. Pancasila mengakui HAM dan agama."},
{id:"TWK-2008",q:"Perbedaan Pancasila dengan ideologi komunisme terletak pada ....",opts:["Pancasila mengakui Ketuhanan Yang Maha Esa","Pancasila menolak keadilan sosial","komunisme mengakui hak milik pribadi mutlak","keduanya menolak musyawarah","Pancasila bersifat materialistis"],a:0,ex:"Komunisme ateis-materialistis menolak Tuhan; Pancasila religius (sila 1). Komunisme menolak milik pribadi, bukan mengakuinya."},
{id:"TWK-2009",q:"Sila kedua Pancasila mengandung nilai kemanusiaan yang berarti ....",opts:["menjunjung tinggi harkat dan martabat manusia secara adil dan beradab","mementingkan bangsa sendiri di atas bangsa lain","mengutamakan kekuatan fisik dalam bergaul","menilai manusia dari harta kekayaannya","membeda-bedakan manusia berdasarkan suku"],a:0,ex:"Kemanusiaan yang adil dan beradab = harkat-martabat manusia universal; bukan nasionalisme sempit, fisik, harta, atau diskriminasi suku."},
{id:"TWK-2010",q:"Contoh pengamalan sila ketiga Pancasila di lingkungan sekolah adalah ....",opts:["bekerja sama membersihkan kelas tanpa membedakan suku teman","beribadah sesuai agama masing-masing","memilih ketua kelas dengan voting","berbagi bekal kepada teman yang tidak membawa","menghargai pendapat teman saat diskusi"],a:0,ex:"Kerja sama lintas suku = persatuan (sila 3); ibadah = sila 1, voting = sila 4, berbagi bekal = sila 2/5, menghargai pendapat = sila 4."},
{id:"TWK-2011",q:"Contoh pengamalan sila kelima Pancasila di masyarakat adalah ....",opts:["pembagian bantuan sosial tepat sasaran kepada yang membutuhkan","pelaksanaan ibadah bersama di rumah ibadah","musyawarah memilih ketua RT","gotong royong membangun pos ronda","menghormati tetangga yang berbeda agama"],a:0,ex:"Bansos tepat sasaran = keadilan sosial (sila 5); ibadah = sila 1, musyawarah = sila 4, gotong royong = sila 3, toleransi = sila 1."},
{id:"TWK-2012",q:"Fungsi pokok Pancasila sebagai ideologi negara adalah ....",opts:["menjadi cita-cita dan pedoman perjuangan bangsa","menjadi alat kekuasaan penguasa","menjadi aturan hukum pidana","menjadi doktrin militer","menjadi sistem ekonomi"],a:0,ex:"Pancasila sebagai ideologi = cita-cita, pedoman perjuangan, pemersatu; bukan alat kekuasaan, KUHP, doktrin militer, atau sistem ekonomi."},
{id:"TWK-2013",q:"Makna Pancasila sebagai kepribadian bangsa Indonesia adalah ....",opts:["mencerminkan ciri khas dan jati diri bangsa Indonesia","hanya berlaku bagi warga negara keturunan","merupakan kepribadian para pemimpin negara","berlaku khusus di lingkungan istana","sama dengan kepribadian bangsa lain"],a:0,ex:"Kepribadian bangsa = jati diri khas Indonesia (ramah, gotong royong, religius); bukan milik pemimpin atau golongan tertentu."},
{id:"TWK-2014",q:"Nilai praksis Pancasila dapat diartikan sebagai ....",opts:["pelaksanaan nilai-nilai Pancasila dalam kehidupan nyata","rumusan abstrak yang tidak dapat dilaksanakan","nilai yang hanya ada dalam teks","ajaran yang bertentangan dengan kenyataan","nilai yang berlaku di masa lalu saja"],a:0,ex:"Nilai praksis = penjabaran nyata nilai dasar dalam kehidupan; bukan rumusan abstrak atau ajaran masa lalu."},
{id:"TWK-2015",q:"Sifat nilai dasar Pancasila adalah ....",opts:["tetap dan tidak berubah","mudah diubah penguasa","relatif mengikuti selera","hanya berlaku sementara","tergantung zaman"],a:0,ex:"Nilai dasar (sila-sila) tetap; yang dinamis adalah penjabaran/instrumentalnya. Inilah makna ideologi terbuka."},
{id:"TWK-2016",q:"Mr. Soepomo mengusulkan dasar negara pada sidang BPUPKI tanggal ....",opts:["31 Mei 1945","29 Mei 1945","1 Juni 1945","22 Juni 1945","10 Juli 1945"],a:0,ex:"Soepomo berpidato 31 Mei 1945; Yamin 29 Mei, Soekarno 1 Juni, Piagam Jakarta 22 Juni."},
{id:"TWK-2017",q:"Usulan dasar negara yang disebut Pancasila oleh Ir. Soekarno pada 1 Juni 1945 terdiri atas ....",opts:["kebangsaan Indonesia, internasionalisme, mufakat, kesejahteraan sosial, ketuhanan","peri kebangsaan, peri kemanusiaan, peri ketuhanan, peri kerakyatan, kesejahteraan","persatuan, kekeluargaan, keseimbangan, musyawarah, keadilan","nasionalisme, agama, komunisme","ketuhanan, kemanusiaan, persatuan, kerakyatan, keadilan"],a:0,ex:"Usulan Soekarno: kebangsaan Indonesia, internasionalisme/peri kemanusiaan, mufakat/demokrasi, kesejahteraan sosial, ketuhanan berkebudayaan. Pilihan kedua milik Yamin, ketiga milik Soepomo."},
{id:"TWK-2018",q:"Piagam Jakarta dijadikan Pembukaan UUD 1945 dengan perubahan pada ....",opts:["sila pertama","sila kedua","sila ketiga","sila keempat","sila kelima"],a:0,ex:"Hanya sila pertama Piagam Jakarta yang diubah PPKI (tujuh kata menjadi Ketuhanan Yang Maha Esa); sila lain tetap."},
{id:"TWK-2019",q:"Tokoh yang mengusulkan perubahan tujuh kata dalam Piagam Jakarta adalah ....",opts:["Mohammad Hatta","Ir. Soekarno","Mr. Soepomo","Ki Bagus Hadikusumo","Wahid Hasyim"],a:0,ex:"Hatta menyampaikan keberatan perwira AL Jepang dan usul perubahan; disetujui PPKI 18 Agustus 1945."},
{id:"TWK-2020",q:"Sila Pancasila yang menjadi sumber nilai bagi sila-sila lainnya karena berkedudukan paling mendasar adalah ....",opts:["sila pertama","sila kedua","sila ketiga","sila keempat","sila kelima"],a:0,ex:"Sila pertama (Ketuhanan) menjiwai sila-sila lain dalam tata urutan hierarkis Pancasila; bukan berarti kedudukannya lebih tinggi secara mutlak."},
{id:"TWK-2021",q:"Pengamalan Pancasila sila keempat dalam kehidupan bernegara contohnya ....",opts:["pemilihan umum yang demokratis","pelaksanaan ibadah haji","pembangunan rumah ibadah","bantuan korban bencana","peringatan hari besar agama"],a:0,ex:"Pemilu demokratis = kedaulatan rakyat/musyawarah (sila 4); ibadah dan hari besar agama = sila 1, bantuan bencana = sila 2/5."},
{id:"TWK-2022",q:"Sikap toleransi antarumat beragama mencerminkan Pancasila sila ....",opts:["pertama","kedua","ketiga","keempat","kelima"],a:0,ex:"Toleransi beragama = pengamalan Ketuhanan Yang Maha Esa (sila 1) yang menghormati kebebasan beragama; bukan sila kemanusiaan/persatuan."},
{id:"TWK-2023",q:"Menjaga kelestarian lingkungan hidup mencerminkan Pancasila sila ....",opts:["kelima","pertama","kedua","ketiga","keempat"],a:0,ex:"Kelestarian lingkungan untuk generasi mendatang = keadilan sosial (sila 5); tafsir umum menempatkannya pada tanggung jawab sosial sila kelima."},
{id:"TWK-2024",q:"Pancasila disahkan sebagai dasar negara pada tanggal ....",opts:["18 Agustus 1945","17 Agustus 1945","1 Juni 1945","22 Juni 1945","27 Desember 1949"],a:0,ex:"PPKI mengesahkan UUD 1945 (dengan Pancasila di Pembukaan) 18 Agustus 1945; 1 Juni hari lahir, 17 Agustus proklamasi."},
{id:"TWK-2025",q:"Kedudukan Pembukaan UUD 1945 yang memuat Pancasila terhadap pasal-pasalnya adalah ....",opts:["sebagai pokok kaidah fundamental yang menjiwai pasal-pasal","sama kedudukannya dengan pasal-pasal","lebih rendah dari batang tubuh","hanya sebagai pembuka tanpa makna hukum","dapat diubah dengan undang-undang biasa"],a:0,ex:"Pembukaan = pokok kaidah fundamental (staatsfundamentalnorm), lebih tinggi dari pasal-pasal dan tidak dapat diubah."},
{id:"TWK-2026",q:"Hari Lahir Pancasila diperingati setiap tanggal ....",opts:["1 Juni","18 Agustus","17 Agustus","22 Juni","20 Mei"],a:0,ex:"Hari Lahir Pancasila 1 Juni (pidato Soekarno 1945), ditetapkan Kepres No. 24/2016; 18 Agustus pengesahan, 17 Agustus kemerdekaan."},
{id:"TWK-2027",q:"Peringatan Hari Kesaktian Pancasila jatuh pada tanggal ....",opts:["1 Oktober","1 Juni","30 September","10 November","20 Mei"],a:0,ex:"Hari Kesaktian Pancasila 1 Oktober memperingati kegagalan G30S; 30 September peristiwa G30S-nya."},
{id:"TWK-2028",q:"Lambang sila pertama Pancasila pada perisai Garuda adalah ....",opts:["bintang","rantai","beringin","banteng","padi dan kapas"],a:0,ex:"Bintang = sila 1 (cahaya ketuhanan); rantai = sila 2, beringin = sila 3, banteng = sila 4, padi-kapas = sila 5."},
{id:"TWK-2029",q:"Warna dasar perisai Garuda Pancasila adalah ....",opts:["merah putih","kuning emas","hitam","hijau","biru"],a:0,ex:"Perisai berlatar merah-putih (bendera nasional) dengan garis hitam tebal; Garuda berwarna kuning emas."},
{id:"TWK-2030",q:"Jumlah bulu leher Garuda Pancasila adalah ....",opts:["45 helai","17 helai","8 helai","19 helai","20 helai"],a:0,ex:"Leher 45 helai (tahun 1945); sayap 17, ekor 8."},
{id:"TWK-2031",q:"Sila Pancasila yang mengandung nilai religiusitas adalah ....",opts:["sila pertama","sila kedua","sila ketiga","sila keempat","sila kelima"],a:0,ex:"Religiusitas = sila pertama (Ketuhanan Yang Maha Esa); sila lain bernilai kemanusiaan, persatuan, kerakyatan, keadilan."},
{id:"TWK-2032",q:"Musyawarah sila keempat Pancasila untuk mencapai mufakat dilandasi semangat ....",opts:["kekeluargaan","individualisme","liberalisme","otoritarianisme","feodalisme"],a:0,ex:"Musyawarah sila keempat berlandaskan semangat kekeluargaan; individualisme, liberalisme, dan otoritarianisme bertentangan."},
{id:"TWK-2033",q:"Sila kelima Pancasila tentang keadilan sosial bagi seluruh rakyat Indonesia mengandung makna ....",opts:["pemerataan kesejahteraan lahir dan batin bagi seluruh rakyat","pembagian harta sama rata tanpa kecuali","penghapusan seluruh perbedaan sosial","negara menanggung seluruh kebutuhan warga","persamaan hasil tanpa memperhatikan usaha"],a:0,ex:"Keadilan sosial = pemerataan kesejahteraan lahir-batin, bukan sama rata mutlak atau negara menanggung segalanya."},
{id:"TWK-2034",q:"Persatuan Indonesia dalam sila ketiga berarti ....",opts:["bersatunya berbagai suku, agama, dan budaya dalam satu bangsa","penyeragaman seluruh adat istiadat daerah","penghapusan identitas suku bangsa","dominasi suku mayoritas atas minoritas","pemisahan urusan agama dan negara"],a:0,ex:"Persatuan = Bhinneka Tunggal Ika (beragam tetapi satu); bukan penyeragaman, penghapusan identitas, atau dominasi mayoritas."},
{id:"TWK-2035",q:"Pasal 28B UUD 1945 memberikan jaminan tentang ....",opts:["hak anak dan keluarga","hak untuk hidup","hak atas pendidikan","hak atas kepastian hukum","hak atas informasi"],a:0,ex:"Pasal 28B: hak membentuk keluarga, keturunan, dan perlindungan anak; hak hidup = 28A, pendidikan = 28C, kepastian hukum = 28D, informasi = 28F."},
{id:"TWK-2036",q:"Pasal 28D UUD 1945 menjamin ....",opts:["pengakuan, jaminan, perlindungan, dan kepastian hukum yang adil","kebebasan memeluk agama","hak memperoleh pelayanan kesehatan","hak atas rasa aman","hak mengembangkan diri"],a:0,ex:"Pasal 28D: kepastian hukum dan perlakuan sama di depan hukum; agama = 28E, kesehatan = 28H, rasa aman = 28G."},
{id:"TWK-2037",q:"Hak yang dijamin dalam Pasal 28F UUD 1945 adalah ....",opts:["hak berkomunikasi dan memperoleh informasi","hak atas pekerjaan","hak memeluk agama","hak atas pendidikan","hak hidup"],a:0,ex:"Pasal 28F: hak berkomunikasi dan memperoleh informasi; pekerjaan = 27 ayat 2, agama = 28E, pendidikan = 28C."},
{id:"TWK-2038",q:"Pasal 28G UUD 1945 menjamin ....",opts:["hak atas rasa aman dan perlindungan dari ancaman","hak atas pekerjaan","hak memeluk agama","hak atas pendidikan","hak hidup"],a:0,ex:"Pasal 28G: rasa aman, bebas dari penyiksaan, hak milik pribadi, dan suaka politik; pekerjaan = 27 ayat 2."},
{id:"TWK-2039",q:"Pasal 28I UUD 1945 menjamin sejumlah hak yang tidak dapat dikurangi dalam keadaan apa pun, contohnya ....",opts:["hak untuk hidup dan kebebasan beragama","hak atas pekerjaan","hak atas pendidikan","hak berkomunikasi","hak atas kepastian hukum"],a:0,ex:"Pasal 28I: hak hidup, tidak disiksa, kemerdekaan pikiran-hati nurani, beragama, tidak diperbudak = non-derogable rights."},
{id:"TWK-2040",q:"Pembatasan hak asasi menurut Pasal 28J UUD 1945 dapat dilakukan dengan ....",opts:["undang-undang","keputusan presiden","peraturan daerah","instruksi menteri","surat edaran"],a:0,ex:"Pasal 28J: pembatasan HAM ditetapkan dengan UU dengan maksud menjamin pengakuan HAM orang lain serta ketertiban umum."},
{id:"TWK-2041",q:"Materi pengaturan Pasal 29 UUD 1945 adalah ....",opts:["agama dan kepercayaan","pertahanan negara","pendidikan","perekonomian","kebudayaan"],a:0,ex:"Pasal 29: negara berdasar Ketuhanan YME dan menjamin kemerdekaan beragama; pertahanan = 30, pendidikan = 31, ekonomi = 33, kebudayaan = 32."},
{id:"TWK-2042",q:"Pasal 30 UUD 1945 mengatur hal-hal mengenai ....",opts:["pertahanan dan keamanan negara","perekonomian nasional","pendidikan nasional","hak asasi manusia","kebebasan beragama"],a:0,ex:"Pasal 30: tiap warga berhak-wajib ikut serta dalam pertahanan-keamanan negara; ekonomi = 33, pendidikan = 31, HAM = 28A-J."},
{id:"TWK-2043",q:"Ketentuan dalam Pasal 32 UUD 1945 mencakup ....",opts:["kebudayaan nasional","pertahanan negara","perekonomian","pendidikan dasar","agama"],a:0,ex:"Pasal 32: negara memajukan kebudayaan nasional dan menjamin kebebasan memelihara-mengembangkan nilai budaya; pendidikan = 31."},
{id:"TWK-2044",q:"Pasal UUD 1945 yang memuat ketentuan 'fakir miskin dan anak-anak terlantar dipelihara oleh negara' adalah Pasal ....",opts:["34","33","32","31","27"],a:0,ex:"Pasal 34: fakir miskin dan anak terlantar dipelihara negara; 33 ekonomi, 32 kebudayaan, 31 pendidikan, 27 hak warga."},
{id:"TWK-2045",q:"Pemilu menurut UUD 1945 berasaskan ....",opts:["langsung, umum, bebas, rahasia, jujur, dan adil","langsung, terbuka, dan cepat","bebas, rahasia, dan tertutup","umum, terbuka, dan sukarela","langsung, umum, dan wajib"],a:0,ex:"Asas pemilu (Pasal 22E): luber jurdil — langsung, umum, bebas, rahasia, jujur, adil."},
{id:"TWK-2046",q:"Jumlah hakim Mahkamah Konstitusi adalah ....",opts:["9 orang","5 orang","7 orang","11 orang","15 orang"],a:0,ex:"MK terdiri dari 9 hakim: 3 diajukan DPR, 3 presiden, 3 MA; diketuai salah satunya."},
{id:"TWK-2047",q:"Grasi dan rehabilitasi menurut UUD 1945 diberikan presiden dengan memperhatikan pertimbangan ....",opts:["Mahkamah Agung","DPR","MPR","DPD","Komisi Yudisial"],a:0,ex:"Pasal 14: presiden memberi grasi-rehabilitasi dengan pertimbangan MA; amnesti-abolisi dengan pertimbangan DPR."},
{id:"TWK-2048",q:"Amnesti dan abolisi menurut UUD 1945 diberikan presiden dengan memperhatikan pertimbangan ....",opts:["DPR","Mahkamah Agung","MPR","DPD","Mahkamah Konstitusi"],a:0,ex:"Pasal 14: amnesti-abolisi dengan pertimbangan DPR; grasi-rehabilitasi dengan pertimbangan MA."},
{id:"TWK-2049",q:"Amandemen kedua UUD 1945 dilaksanakan pada tahun ....",opts:["2000","1999","2001","2002","1998"],a:0,ex:"Amandemen II ditetapkan 18 Agustus 2000 (25 pasal, HAM dan otonomi); I 1999, III 2001, IV 2002."},
{id:"TWK-2050",q:"Materi utama amandemen ketiga UUD 1945 adalah ....",opts:["kedaulatan rakyat dan lembaga-lembaga negara","hak asasi manusia","otonomi daerah","pemilihan presiden langsung","dewan perwakilan daerah"],a:0,ex:"Amandemen III (2001): kedaulatan rakyat, lembaga negara, pemilihan presiden; HAM = amandemen II, DPD = amandemen IV."},
{id:"TWK-2051",q:"Amandemen keempat UUD 1945 dilaksanakan pada tahun ....",opts:["2002","1999","2000","2001","1998"],a:0,ex:"Amandemen IV ditetapkan 10 Agustus 2002 (19 pasal); I 1999, II 2000, III 2001."},
{id:"TWK-2052",q:"Materi utama amandemen keempat UUD 1945 adalah ....",opts:["pendidikan, kebudayaan, dan perekonomian nasional","hak asasi manusia","otonomi daerah","kedaulatan rakyat","lembaga perwakilan"],a:0,ex:"Amandemen IV (2002): Pasal 31 pendidikan, 32 kebudayaan, 33-34 ekonomi-kesejahteraan; HAM = amandemen II, kedaulatan = III."},
{id:"TWK-2053",q:"Rancangan undang-undang yang dapat diajukan DPD kepada DPR berkaitan dengan ....",opts:["otonomi daerah","pertahanan negara","politik luar negeri","sistem peradilan","keuangan negara"],a:0,ex:"DPD berinisiatif RUU bidang otonomi daerah, hubungan pusat-daerah, dan pertimbangan terkait; pertahanan dan luar negeri bukan bidang DPD."},
{id:"TWK-2054",q:"Fungsi pengawasan DPD berkaitan dengan ....",opts:["pelaksanaan otonomi daerah","pelaksanaan APBN","kebijakan luar negeri","pengangkatan menteri","putusan pengadilan"],a:0,ex:"DPD mengawasi pelaksanaan UU otonomi daerah, pembentukan-pemekaran daerah, dan perimbangan keuangan; APBN diawasi DPR."},
{id:"TWK-2055",q:"Presiden berhak mengajukan rancangan undang-undang kepada DPR menurut Pasal .... UUD 1945",opts:["5","4","6","7","20"],a:0,ex:"Pasal 5 ayat (1): presiden berhak mengajukan RUU; Pasal 4 kekuasaan pemerintahan, Pasal 20 pembentukan UU oleh DPR."},
{id:"TWK-2056",q:"Rancangan undang-undang yang tidak mendapat persetujuan bersama DPR dan presiden tidak boleh diajukan lagi dalam ....",opts:["masa persidangan itu","satu tahun anggaran","lima tahun","dua masa persidangan","waktu yang tidak ditentukan"],a:0,ex:"Pasal 20 ayat (3): RUU yang tidak disetujui bersama tidak boleh diajukan lagi dalam persidangan masa itu."},
{id:"TWK-2057",q:"Hak imunitas anggota DPR berarti ....",opts:["tidak dapat dituntut karena pernyataan dan pendapat dalam rapat dewan","bebas dari segala tuntutan hukum selamanya","kebal terhadap pemeriksaan polisi","tidak wajib membayar pajak","bebas melakukan tindak pidana"],a:0,ex:"Imunitas = kekebalan atas pernyataan/pendapat dalam tugas dewan; bukan kebal hukum total atau bebas tindak pidana."},
{id:"TWK-2058",q:"MPR terdiri atas ....",opts:["anggota DPR dan anggota DPD","menteri dan gubernur","hakim agung dan jaksa agung","duta besar dan konsul","ketua partai politik"],a:0,ex:"Pasal 2: MPR terdiri dari anggota DPR dan DPD yang dipilih lewat pemilu; bukan menteri, hakim, atau ketua parpol."},
{id:"TWK-2059",q:"Sidang MPR diadakan sedikitnya sekali dalam ....",opts:["lima tahun","satu tahun","dua tahun","tiga tahun","sepuluh tahun"],a:0,ex:"MPR bersidang minimal sekali dalam lima tahun di ibu kota negara (Pasal 2 ayat 2)."},
{id:"TWK-2060",q:"Menurut UUD 1945, kekuasaan tertinggi atas angkatan darat, angkatan laut, dan angkatan udara dipegang oleh ....",opts:["presiden","panglima TNI","menteri pertahanan","DPR","MPR"],a:0,ex:"Pasal 10: presiden memegang kekuasaan tertinggi atas AD, AL, AU; panglima TNI di bawah presiden."},
{id:"TWK-2061",q:"Presiden mengangkat duta dan konsul menurut UUD 1945 dengan memperhatikan pertimbangan ....",opts:["DPR","MPR","DPD","Mahkamah Agung","partai politik"],a:0,ex:"Pasal 13: presiden mengangkat duta-konsul dengan memperhatikan pertimbangan DPR; menerima duta negara lain juga demikian."},
{id:"TWK-2062",q:"Ketentuan bahwa Indonesia adalah negara hukum ditegaskan dalam Pasal .... UUD 1945",opts:["1 ayat (3)","1 ayat (1)","1 ayat (2)","2 ayat (1)","4 ayat (1)"],a:0,ex:"Pasal 1 ayat (3): Indonesia adalah negara hukum; ayat (1) bentuk negara, ayat (2) kedaulatan rakyat."},
{id:"TWK-2063",q:"Kedaulatan berada di tangan rakyat ditegaskan dalam Pasal .... UUD 1945",opts:["1 ayat (2)","1 ayat (1)","1 ayat (3)","2 ayat (1)","27 ayat (1)"],a:0,ex:"Pasal 1 ayat (2): kedaulatan di tangan rakyat dilaksanakan menurut UUD; ayat (1) bentuk negara kesatuan-republik."},
{id:"TWK-2064",q:"Menurut UUD 1945, bentuk pemerintahan Indonesia adalah ....",opts:["republik","monarki","federal","teokrasi","oligarki"],a:0,ex:"Pasal 1 ayat (1): Indonesia ialah negara kesatuan yang berbentuk republik; bukan monarki, federal, atau teokrasi."},
{id:"TWK-2065",q:"Pasal 36A UUD 1945 menetapkan ....",opts:["lambang negara","bendera negara","bahasa negara","lagu kebangsaan","ibu kota negara"],a:0,ex:"Pasal 36A: lambang negara Garuda Pancasila; 35 bendera, 36 bahasa, 36B lagu kebangsaan."},
{id:"TWK-2066",q:"Objek pengaturan Pasal 35 UUD 1945 adalah ....",opts:["bendera negara Sang Merah Putih","lambang negara","bahasa negara","lagu kebangsaan","wilayah negara"],a:0,ex:"Pasal 35: bendera negara Sang Merah Putih; 36A lambang, 36 bahasa, 36B lagu, 25A wilayah."},
{id:"TWK-2067",q:"Ketentuan bahasa negara adalah bahasa Indonesia ditegaskan dalam Pasal .... UUD 1945",opts:["36","35","36A","36B","25A"],a:0,ex:"Pasal 36: bahasa negara ialah bahasa Indonesia; 35 bendera, 36A lambang, 36B lagu kebangsaan."},
{id:"TWK-2068",q:"Lagu kebangsaan adalah Indonesia Raya ditegaskan dalam Pasal .... UUD 1945",opts:["36B","36","36A","35","25A"],a:0,ex:"Pasal 36B: lagu kebangsaan ialah Indonesia Raya; 36 bahasa, 36A lambang, 35 bendera."},
{id:"TWK-2069",q:"Pengelolaan sumber daya nasional untuk bela negara diatur dalam ....",opts:["UU No. 23 Tahun 2019 tentang PSDN","UU No. 3 Tahun 2002 tentang Pertahanan Negara","UU No. 34 Tahun 2004 tentang TNI","UU No. 2 Tahun 2002 tentang Polri","UU No. 5 Tahun 2014 tentang ASN"],a:0,ex:"UU 23/2019 (PSDN) mengatur pengelolaan SDM, SDA, sarana untuk pertahanan; UU 3/2002 pertahanan umum, UU 34/2004 TNI."},
{id:"TWK-2070",q:"Wujud bela negara yang bersifat fisik adalah ....",opts:["mengikuti pelatihan dasar kemiliteran","mengikuti seminar kebangsaan","menulis artikel patriotik","berdiskusi tentang negara","menonton film perjuangan"],a:0,ex:"Fisik = latihan kemiliteran/komcad; seminar, artikel, diskusi, film adalah bela negara nonfisik."},
{id:"TWK-2071",q:"Bela negara secara nonfisik dapat diwujudkan melalui ....",opts:["meningkatkan kesadaran berbangsa dan bernegara","mengikuti wajib militer","latihan menembak","baris-berbaris","bela diri militer"],a:0,ex:"Nonfisik = kesadaran, profesi, karya; wajib militer, menembak, dan baris adalah fisik/militer."},
{id:"TWK-2072",q:"Nilai cinta tanah air dalam bela negara diwujudkan dengan ....",opts:["bangga menggunakan bahasa Indonesia","menolak bahasa asing","hanya bergaul dengan sebangsa","menutup diri dari dunia luar","mengklaim budaya negara lain"],a:0,ex:"Cinta tanah air = bangga bahasa, budaya, produk sendiri; bukan menolak asing, eksklusif, atau klaim budaya."},
{id:"TWK-2073",q:"Nilai sadar berbangsa dan bernegara dalam bela negara diwujudkan dengan ....",opts:["menempatkan persatuan di atas kepentingan pribadi","mementingkan suku sendiri","menolak perbedaan pendapat","mengutamakan golongan sendiri","acuh terhadap negara"],a:0,ex:"Sadar berbangsa = persatuan di atas pribadi/golongan; primordialisme dan apatisme bertentangan dengannya."},
{id:"TWK-2074",q:"Kesetiaan pada ideologi bangsa sebagai nilai dasar bela negara diwujudkan dengan ....",opts:["mengamalkan nilai-nilainya dalam kehidupan sehari-hari","menghafal teks ideologi di luar kepala","memaksa orang lain mengikuti","menjadikannya alat kekuasaan","cukup mengetahui tanpa mengamalkan"],a:0,ex:"Setia ideologi = mengamalkan nilainya, bukan hafalan, pemaksaan, alat kekuasaan, atau sekadar tahu."},
{id:"TWK-2075",q:"Ancaman terhadap ideologi bangsa dalam konteks bela negara dapat berupa ....",opts:["propaganda yang memecah belah persatuan","perbedaan pendapat yang sehat","kritik membangun pemerintah","diskusi ilmiah di kampus","kebebasan pers bertanggung jawab"],a:0,ex:"Propaganda pemecah belah = ancaman ideologi; kritik, diskusi, dan pers bebas yang sehat bukan ancaman."},
{id:"TWK-2076",q:"Upaya bela negara menghadapi ancaman di bidang politik adalah ....",opts:["memperkuat demokrasi dan supremasi hukum","membatasi kebebasan berpendapat","menghapus pemilihan umum","memusatkan seluruh kekuasaan","menutup ruang dialog"],a:0,ex:"Ancaman politik dihadapi dengan demokrasi dan hukum yang kuat; pembatasan kebebasan dan sentralisasi justru melemahkan."},
{id:"TWK-2077",q:"Ketahanan ekonomi sebagai bagian bela negara diwujudkan dengan ....",opts:["mencintai dan menggunakan produk dalam negeri","menolak investasi asing sepenuhnya","menutup keran impor total","berbelanja produk luar negeri","bergantung pada utang luar negeri"],a:0,ex:"Ketahanan ekonomi = cinta produk dalam negeri dan kemandirian; bukan menolak investasi/impor total atau bergantung utang."},
{id:"TWK-2078",q:"Peran pemuda dalam upaya bela negara adalah ....",opts:["menjadi generasi yang cerdas dan berkarakter","menjadi penonton pembangunan","menunggu perintah orang tua","fokus pada kepentingan pribadi","menghindari organisasi"],a:0,ex:"Pemuda = generasi penerus yang cerdas-berkarakter; bukan penonton, apatis, atau individualis."},
{id:"TWK-2079",q:"Peran perempuan dalam upaya bela negara adalah ....",opts:["sama dengan laki-laki sesuai kemampuan dan profesinya","hanya mengurus rumah tangga","tidak perlu ikut serta","sebagai pelengkap saja","terbatas pada bidang tertentu"],a:0,ex:"Bela negara hak-kewajiban seluruh warga tanpa diskriminasi gender; perempuan berperan sesuai kemampuan dan profesi."},
{id:"TWK-2080",q:"Sikap waspada terhadap ancaman dapat ditunjukkan dengan ....",opts:["tidak mudah terprovokasi isu SARA","menyebarkan setiap berita yang diterima","mudah percaya ujaran kebencian","ikut menyebarkan hoaks","acuh terhadap lingkungan"],a:0,ex:"Waspada = kritis terhadap provokasi SARA dan hoaks; menyebar berita tanpa verifikasi justru memperlemah."},
{id:"TWK-2081",q:"Literasi digital sebagai wujud bela negara berarti ....",opts:["bijak bermedia sosial dan melawan hoaks","memiliki banyak pengikut media sosial","mahir menggunakan gawai terbaru","sering mengunggah kegiatan pribadi","aktif berkomentar di setiap unggahan"],a:0,ex:"Literasi digital = cakap, bijak, dan melawan disinformasi; bukan soal pengikut, gawai, atau unggahan."},
{id:"TWK-2082",q:"Hoaks yang memecah belah bangsa termasuk ancaman ....",opts:["nonmiliter","militer","hibrida","agresi","spionase"],a:0,ex:"Hoaks/disinformasi = ancaman nonmiliter bidang informasi; bukan militer karena tanpa kekuatan senjata."},
{id:"TWK-2083",q:"Radikalisme sebagai ancaman bangsa harus dihadapi dengan ....",opts:["deradikalisasi dan penguatan moderasi beragama","kekerasan fisik semata","pembiaran tanpa tindakan","pengusiran penganutnya","pelarangan seluruh kegiatan agama"],a:0,ex:"Radikalisme dihadapi dengan deradikalisasi, moderasi, dan penegakan hukum; kekerasan semata atau pelarangan agama bukan solusi."},
{id:"TWK-2084",q:"Aksi teror bersenjata termasuk ancaman ....",opts:["militer","nonmiliter bidang ekonomi","nonmiliter bidang politik","keselamatan umum","ancaman potensial"],a:0,ex:"Teror bersenjata menggunakan kekuatan senjata sehingga dikategorikan ancaman militer dalam doktrin pertahanan."},
{id:"TWK-2085",q:"Sabotase terhadap instalasi vital negara termasuk ancaman ....",opts:["militer","nonmiliter bidang ekonomi","nonmiliter bidang politik","keselamatan umum","ancaman nirbentuk"],a:0,ex:"Sabotase instalasi vital = ancaman militer; ancaman ekonomi-politik tidak melibatkan perusakan fisik bersenjata."},
{id:"TWK-2086",q:"Bentuk ancaman nonmiliter di bidang teknologi adalah ....",opts:["serangan siber terhadap data nasional","agresi militer negara tetangga","pemberontakan bersenjata","spionase agen asing","pelanggaran wilayah udara"],a:0,ex:"Serangan siber = nonmiliter bidang teknologi; agresi, pemberontakan, spionase, pelanggaran wilayah = militer."},
{id:"TWK-2087",q:"Upaya bela negara di lingkungan keluarga adalah ....",opts:["menanamkan nilai patriotisme pada anak","memaksa anak menjadi tentara","melarang anak bergaul","menuntut anak serba bisa","membebaskan anak tanpa aturan"],a:0,ex:"Keluarga menanamkan patriotisme dan karakter; bukan memaksa profesi, melarang bergaul, atau membebaskan tanpa aturan."},
{id:"TWK-2088",q:"Upaya bela negara di lingkungan sekolah adalah ....",opts:["mengikuti upacara dan organisasi dengan tertib","hanya mengejar nilai akademik","tawuran antar sekolah","mencontek saat ujian","bolos kegiatan sekolah"],a:0,ex:"Sekolah: disiplin upacara, organisasi, prestasi; tawuran, mencontek, dan bolos bertentangan dengan bela negara."},
{id:"TWK-2089",q:"Upaya bela negara di lingkungan masyarakat adalah ....",opts:["aktif dalam kegiatan sosial kemasyarakatan","acuh terhadap lingkungan","menolak gotong royong","menyebarkan permusuhan","mementingkan diri sendiri"],a:0,ex:"Masyarakat: gotong royong, ronda, kerja bakti; apatisme, permusuhan, dan individualisme melemahkan ketahanan sosial."},
{id:"TWK-2090",q:"Semangat juang para pahlawan sebagai teladan bela negara adalah ....",opts:["rela berkorban tanpa pamrih","berjuang demi jabatan","mengharap imbalan materi","mencari popularitas","mengutamakan keselamatan diri"],a:0,ex:"Pahlawan rela berkorban tanpa pamrih; motif jabatan, materi, dan popularitas bertentangan dengan semangat juang."},
{id:"TWK-2091",q:"Ciri perjuangan bela negara bangsa Indonesia adalah ....",opts:["ditempuh melalui perjuangan fisik dan diplomasi","hanya mengandalkan senjata","hanya melalui perundingan","menyerah pada kekuatan besar","bergantung pada bantuan asing"],a:0,ex:"Perjuangan Indonesia memadukan fisik (pertempuran) dan diplomasi (perundingan); bukan salah satu saja atau menyerah."},
{id:"TWK-2092",q:"Tujuan sishankamrata adalah ....",opts:["menjamin keutuhan dan kedaulatan negara","memperluas wilayah negara","menyerang negara lain","menunjukkan kekuatan militer","mengurangi peran rakyat"],a:0,ex:"Sishankamrata bertujuan defensif: keutuhan-kedaulatan negara; bukan ekspansi, agresi, atau unjuk kekuatan."},
{id:"TWK-2093",q:"Prinsip sishankamrata adalah ....",opts:["kerakyatan, kesemestaan, dan kewilayahan","ofensif, agresif, dan ekspansif","sentralistis dan tertutup","individual dan liberal","feodal dan militeristis"],a:0,ex:"Prinsip sishankamrata: kerakyatan (didukung rakyat), kesemestaan (seluruh sumber daya), kewilayahan (gelar di wilayah)."},
{id:"TWK-2094",q:"Komponen cadangan dimobilisasi pada saat ....",opts:["negara dalam keadaan bahaya atau perang","setiap tahun anggaran baru","latihan rutin tahunan","upacara kenegaraan","pemilihan umum"],a:0,ex:"Komcad dimobilisasi saat negara terancam/bahaya melalui keputusan presiden; bukan agenda rutin tahunan."},
{id:"TWK-2095",q:"Sumber daya manusia untuk komponen pendukung berasal dari ....",opts:["seluruh warga negara sesuai profesi dan keahliannya","hanya prajurit TNI aktif","hanya pegawai negeri sipil","hanya anggota kepolisian","hanya lulusan akademi militer"],a:0,ex:"Komponen pendukung = warga negara sesuai profesi (dokter, insinyur, dsb.); bukan terbatas pada TNI/PNS/polisi."},
{id:"TWK-2096",q:"Ketahanan nasional bersifat ....",opts:["dinamis mengikuti perkembangan zaman","statis tidak berubah","kaku dan tertutup","sementara waktu","terbatas pada militer"],a:0,ex:"Ketahanan nasional dinamis: keuletan-ketangguhan menyesuaikan ancaman zaman; bukan statis, kaku, atau semata militer."},
{id:"TWK-2097",q:"Faktor yang memengaruhi ketahanan nasional adalah ....",opts:["trigatra dan pancagatra","jumlah penduduk saja","luas wilayah saja","kekuatan militer saja","bantuan luar negeri"],a:0,ex:"Ketahanan nasional dipengaruhi delapan gatra (astagatra); bukan faktor tunggal seperti penduduk, wilayah, atau militer."},
{id:"TWK-2098",q:"Contoh ketahanan nasional di bidang ideologi adalah ....",opts:["pengamalan nilai-nilai luhur bangsa","penambahan jumlah tentara","pembangunan pangkalan militer","peningkatan anggaran pertahanan","pengadaan alat utama sistem senjata"],a:0,ex:"Ketahanan ideologi = pengamalan nilai luhur (Pancasila); penambahan tentara dan alutsista = ketahanan hankam."},
{id:"TWK-2099",q:"Contoh ketahanan nasional di bidang sosial budaya adalah ....",opts:["pelestarian adat dan budaya daerah","pembangunan mal dan apartemen","peningkatan impor barang","penutupan sanggar seni","penghapusan bahasa daerah"],a:0,ex:"Ketahanan sosbud = melestarikan adat-budaya daerah; pembangunan mal, impor, dan penghapusan budaya justru melemahkan."},
{id:"TWK-2100",q:"Hakikat bela negara bagi seorang pelajar adalah ....",opts:["belajar sungguh-sungguh untuk kemajuan bangsa","berlatih kemiliteran setiap hari","menjadi anggota TNI","mengikuti demonstrasi","menolak seluruh aturan sekolah"],a:0,ex:"Bela negara pelajar = belajar tekun, disiplin, berprestasi untuk bangsa; bukan latihan militer harian atau demonstrasi."},
{id:"TWK-2101",q:"Sikap patriotisme dalam bela negara ditunjukkan dengan ....",opts:["membela kehormatan bangsa dalam setiap tindakan","membanggakan diri secara berlebihan","merendahkan bangsa lain","menolak kritik membangun","mengagungkan masa lalu"],a:0,ex:"Patriotisme = membela kehormatan bangsa lewat tindakan nyata; bukan chauvinisme, merendahkan bangsa lain, atau menolak kritik."},
{id:"TWK-2102",q:"Hak oktroi yang dimiliki VOC adalah ....",opts:["hak istimewa berdagang, mencetak uang, dan memiliki tentara","hak memungut pajak dari rakyat pribumi","hak mengangkat raja-raja lokal","hak menyebarkan agama Kristen","hak membangun sekolah dan gereja"],a:0,ex:"Hak oktroi VOC: monopoli dagang, mencetak uang, berdiplomasi, memiliki tentara, mendirikan benteng; bukan memungut pajak langsung atau mengangkat raja."},
{id:"TWK-2103",q:"Gubernur Jenderal Daendels pada masa penjajahan Belanda terkenal dengan kebijakannya ....",opts:["membangun Jalan Raya Anyer-Panarukan","menerapkan sistem tanam paksa","memberlakukan sistem sewa tanah","mendirikan VOC","membubarkan VOC"],a:0,ex:"Daendels (1808-1811) membangun jalan Anyer-Panarukan; tanam paksa = Van den Bosch, sewa tanah = Raffles, VOC berdiri 1602 bubar 1799."},
{id:"TWK-2104",q:"Pada masa penjajahan Inggris, Indonesia dipimpin oleh ....",opts:["Thomas Stamford Raffles","Gubernur Jenderal Daendels","Van den Bosch","Lord Minto","Jan Pieterszoon Coen"],a:0,ex:"Raffles memimpin Jawa 1811-1816 (Letnan Gubernur); Daendels dan Van den Bosch era Belanda, Lord Minto atasan Raffles di India."},
{id:"TWK-2105",q:"Sistem sewa tanah (landrent) diberlakukan pada masa penjajahan ....",opts:["Inggris","Belanda","Jepang","Portugis","Prancis"],a:0,ex:"Landrent diberlakukan Raffles (Inggris); tanam paksa era Belanda (Van den Bosch), romusha era Jepang."},
{id:"TWK-2106",q:"Organisasi pergerakan Sarekat Islam didirikan pada tahun ....",opts:["1912","1908","1927","1928","1926"],a:0,ex:"Sarekat Islam (1912) lanjutan SDI (1911) oleh Tjokroaminoto; 1908 Budi Utomo, 1927 PNI, 1928 Sumpah Pemuda."},
{id:"TWK-2107",q:"Tokoh pergerakan pendiri Sarekat Islam adalah ....",opts:["H.O.S. Tjokroaminoto","Ki Hajar Dewantara","Haji Agus Salim","Douwes Dekker","Tjipto Mangunkusumo"],a:0,ex:"Sarekat Islam dipimpin Tjokroaminoto; tokoh lain dari Indische Partij atau organisasi berbeda."},
{id:"TWK-2108",q:"Organisasi pergerakan Muhammadiyah didirikan oleh K.H. Ahmad Dahlan pada tahun ....",opts:["1912","1926","1908","1928","1922"],a:0,ex:"Muhammadiyah berdiri 18 November 1912 di Yogyakarta; NU 1926, Taman Siswa 1922."},
{id:"TWK-2109",q:"Organisasi pergerakan Nahdlatul Ulama didirikan pada tahun ....",opts:["1926","1912","1908","1928","1922"],a:0,ex:"NU berdiri 31 Januari 1926 di Surabaya oleh K.H. Hasyim Asy'ari; Muhammadiyah 1912, Taman Siswa 1922."},
{id:"TWK-2110",q:"Taman Siswa sebagai organisasi pergerakan pendidikan didirikan Ki Hajar Dewantara pada tahun ....",opts:["1922","1912","1926","1908","1928"],a:0,ex:"Taman Siswa berdiri 3 Juli 1922 di Yogyakarta; Muhammadiyah 1912, NU 1926."},
{id:"TWK-2111",q:"Semboyan Taman Siswa pada masa pergerakan nasional 'Tut Wuri Handayani' berarti ....",opts:["dari belakang memberi dorongan","di depan memberi teladan","di tengah membangun semangat","dari samping memberi bantuan","dari atas memberi perintah"],a:0,ex:"Tiga semboyan: Ing ngarso sung tulodo (depan teladan), Ing madyo mangun karso (tengah semangat), Tut wuri handayani (belakang dorongan)."},
{id:"TWK-2112",q:"PETA dibentuk oleh Jepang pada tahun ....",opts:["1943","1942","1944","1945","1941"],a:0,ex:"PETA (Pembela Tanah Air) dibentuk 3 Oktober 1943; 1942 Jepang mendarat, 1945 kemerdekaan."},
{id:"TWK-2113",q:"Tujuan Jepang membentuk PETA adalah ....",opts:["membantu Jepang dalam Perang Asia Timur Raya","memerdekakan Indonesia","melatih guru-guru Indonesia","membangun ekonomi rakyat","menyebarkan bahasa Jepang"],a:0,ex:"PETA dibentuk untuk membantu perang Jepang; namun menjadi cikal bakal TNI setelah kemerdekaan."},
{id:"TWK-2114",q:"Romusha pada masa Jepang adalah ....",opts:["pekerja paksa untuk kepentingan perang Jepang","tentara sukarela Indonesia","pegawai administrasi Jepang","guru bahasa Jepang","pedagang pasar"],a:0,ex:"Romusha = pekerja paksa (buruh kasar) yang menderita; bukan tentara sukarela (PETA/Heiho) atau pegawai."},
{id:"TWK-2115",q:"Rumah tempat dirumuskannya teks proklamasi kemerdekaan adalah ....",opts:["kediaman Laksamana Maeda","kediaman Ir. Soekarno","kediaman Drs. Mohammad Hatta","Gedung Merdeka","Istana Merdeka"],a:0,ex:"Teks proklamasi dirumuskan di rumah Laksamana Tadashi Maeda (Jl. Imam Bonjol 1); dibacakan di kediaman Soekarno."},
{id:"TWK-2116",q:"Tokoh yang menjamin proklamasi kemerdekaan dilaksanakan pada 17 Agustus 1945 adalah ....",opts:["Ahmad Soebardjo","Sayuti Melik","B.M. Diah","Soekarni","Wikana"],a:0,ex:"Ahmad Soebardjo menjamin keamanan dan meyakinkan golongan muda agar proklamasi 17 Agustus; Wikana-Soekarni golongan muda pendesak."},
{id:"TWK-2117",q:"Pertempuran Palagan Ambarawa dalam mempertahankan kemerdekaan dipimpin oleh ....",opts:["Kolonel Soedirman","Jenderal Nasution","Bung Tomo","Gubernur Suryo","Slamet Riyadi"],a:0,ex:"Soedirman memimpin Palagan Ambarawa (Des 1945) mengusir Sekutu; diabadikan Monumen Palagan Ambarawa."},
{id:"TWK-2118",q:"Pertempuran Ambarawa dalam mempertahankan kemerdekaan terjadi pada ....",opts:["15 Desember 1945","10 November 1945","24 Maret 1946","21 Juli 1947","19 Desember 1948"],a:0,ex:"Palagan Ambarawa 12-15 Desember 1945 (puncak 15 Des, Hari Juang Kartika); Surabaya 10 Nov 1945, Bandung Lautan Api 24 Mar 1946."},
{id:"TWK-2119",q:"Peristiwa Medan Area dalam masa revolusi fisik terjadi karena ....",opts:["ultimatum Sekutu agar pemuda menyerahkan senjata","pendaratan tentara Jepang","perebutan kekuasaan antarpemuda","penolakan hasil perundingan","pembentukan negara boneka"],a:0,ex:"Ultimatum Sekutu di Medan (Oktober 1945) memicu perlawanan pemuda; dipimpin Achmad Tahir."},
{id:"TWK-2120",q:"Perundingan Roem-Royen sebagai tindak lanjut agresi militer Belanda menghasilkan ....",opts:["penghentian permusuhan dan kembalinya pemerintah RI ke Yogyakarta","pengakuan kedaulatan penuh","pembentukan RIS","penarikan tentara Belanda seketika","gencatan senjata sepihak"],a:0,ex:"Roem-Royen (7 Mei 1949): gencatan senjata, RI kembali ke Yogya, KMB; kedaulatan penuh baru di KMB."},
{id:"TWK-2121",q:"Delegasi Indonesia dalam KMB dipimpin oleh ....",opts:["Drs. Mohammad Hatta","Ir. Soekarno","Sutan Syahrir","Mr. Soepomo","Haji Agus Salim"],a:0,ex:"Delegasi RI di KMB dipimpin Hatta; BFO dipimpin Sultan Hamid II, Belanda Van Maarseveen."},
{id:"TWK-2122",q:"Hasil KMB bagi Indonesia adalah pembentukan ....",opts:["Republik Indonesia Serikat","Negara Kesatuan RI","Republik Indonesia Yogyakarta","Negara Indonesia Timur","Republik Perserikatan"],a:0,ex:"KMB menghasilkan RIS (27 Des 1949) sebagai negara federal; kembali ke NKRI 17 Agustus 1950."},
{id:"TWK-2123",q:"RIS hasil KMB bubar dan kembali menjadi negara kesatuan pada ....",opts:["17 Agustus 1950","27 Desember 1949","17 Agustus 1945","5 Juli 1959","21 Mei 1998"],a:0,ex:"RIS bubar 17 Agustus 1950 kembali ke NKRI; 27 Des 1949 penyerahan kedaulatan, 5 Jul 1959 Dekrit."},
{id:"TWK-2124",q:"Pada masa Orde Lama, konsep Nasakom dicetuskan oleh ....",opts:["Soekarno","Soeharto","Sjahrir","Hatta","Nasution"],a:0,ex:"Nasakom (Nasionalisme-Agama-Komunisme) dicetuskan Soekarno era Demokrasi Terpimpin; bukan dari tokoh lain."},
{id:"TWK-2125",q:"Pada masa Orde Lama, Nasakom adalah singkatan dari ....",opts:["nasionalisme, agama, komunisme","nasionalisme, adat, komunitas","nasi, akomodasi, komunikasi","nasional, agraris, komunis","nara, sabda, koma"],a:0,ex:"Nasakom = Nasionalisme, Agama, Komunisme sebagai ajaran Demokrasi Terpimpin Soekarno."},
{id:"TWK-2126",q:"Pada masa peralihan Orde Lama, Supersemar memberi wewenang kepada Soeharto untuk ....",opts:["memulihkan keamanan dan ketertiban","menyusun undang-undang dasar","membentuk kabinet baru","mengadakan pemilihan umum","membubarkan DPR"],a:0,ex:"Supersemar (11 Mar 1966): wewenang memulihkan keamanan pasca G30S; menjadi dasar lahirnya Orde Baru."},
{id:"TWK-2127",q:"Tritura pada masa akhir Orde Lama berisi ....",opts:["bubarkan PKI, rombak kabinet, turunkan harga","turunkan Soekarno, bentuk presidium, adili koruptor","bentuk DPR baru, sita harta, hukum mati","bubar parlemen, pemilu ulang, otonomi","nasionalisasi asing, swasembada, transmigrasi"],a:0,ex:"Tritura (10 Jan 1966): pembubaran PKI, perombakan kabinet Dwikora, penurunan harga/perbaikan ekonomi."},
{id:"TWK-2128",q:"Pemilu pertama pada masa Orde Baru dilaksanakan tahun ....",opts:["1971","1977","1955","1982","1966"],a:0,ex:"Pemilu Orde Baru pertama 1971 (Golkar menang); pemilu 1955 era demokrasi liberal; Orde Baru rutin tiap 5 tahun."},
{id:"TWK-2129",q:"Program Repelita pada masa Orde Baru bertujuan ....",opts:["pembangunan ekonomi nasional bertahap","pembangunan militer besar-besaran","nasionalisasi perusahaan asing","penghapusan utang luar negeri","pemerataan jabatan politik"],a:0,ex:"Repelita (Rencana Pembangunan Lima Tahun) fokus ekonomi; bukan militer, nasionalisasi, atau politik."},
{id:"TWK-2130",q:"Provinsi Timor Timur terbentuk pada masa Orde Baru tahun ....",opts:["1976","1975","1974","1979","1980"],a:0,ex:"Timor Timur berintegrasi 1976 (UU No. 7/1976); lepas lewat referendum 1999."},
{id:"TWK-2131",q:"Krisis moneter 1997 yang memicu gerakan reformasi berawal dari negara ....",opts:["Thailand","Indonesia","Malaysia","Korea Selatan","Jepang"],a:0,ex:"Krisis Asia 1997 bermula dari jatuhnya baht Thailand Juli 1997 lalu merembet ke Indonesia."},
{id:"TWK-2132",q:"Pada masa reformasi, Presiden B.J. Habibie mengambil kebijakan ....",opts:["memberi kesempatan referendum bagi Timor Timur","mencabut dwifungsi ABRI","mengadakan pemilu 1955","menetapkan Repelita","membubarkan PKI"],a:0,ex:"Habibie (1998-1999): referendum Timtim, kebebasan pers, UU parpol; dwifungsi dihapus bertahap era reformasi."},
{id:"TWK-2133",q:"Tuntutan reformasi di bidang politik antara lain ....",opts:["penghapusan dwifungsi ABRI","penguatan dwifungsi ABRI","pembatasan kebebasan pers","sentralisasi kekuasaan","penghapusan pemilihan umum"],a:0,ex:"Reformasi menuntut hapus dwifungsi, kebebasan pers, otonomi, HAM; bukan sebaliknya."},
{id:"TWK-2134",q:"Era reformasi lahir ditandai dengan mundurnya Soeharto pada ....",opts:["21 Mei 1998","11 Maret 1966","5 Juli 1959","30 September 1965","17 Agustus 1945"],a:0,ex:"Soeharto mundur 21 Mei 1998; Supersemar 1966, Dekrit 1959, G30S 1965."},
{id:"TWK-2135",q:"Kedudukan Sekretariat ASEAN berada di ....",opts:["Jakarta","Bangkok","Kuala Lumpur","Manila","Singapura"],a:0,ex:"Sekretariat ASEAN di Jakarta (dibuka 1976); Bangkok tempat deklarasi, bukan sekretariat."},
{id:"TWK-2136",q:"Bahasa resmi yang digunakan dalam sidang-sidang ASEAN adalah ....",opts:["bahasa Inggris","bahasa Indonesia","bahasa Melayu","bahasa Thailand","bahasa Arab"],a:0,ex:"Bahasa kerja ASEAN adalah bahasa Inggris; bukan bahasa negara anggota tertentu."},
{id:"TWK-2137",q:"KTT ASEAN pertama diselenggarakan di ....",opts:["Bali, Indonesia","Bangkok, Thailand","Kuala Lumpur, Malaysia","Manila, Filipina","Singapura"],a:0,ex:"KTT I ASEAN 1976 di Bali menghasilkan Deklarasi Concordia; KTT rutin kemudian bergilir."},
{id:"TWK-2138",q:"Tujuan pembentukan Masyarakat Ekonomi ASEAN (MEA) adalah ....",opts:["mewujudkan pasar tunggal dan basis produksi","membentuk mata uang tunggal","menghapus seluruh pemerintahan nasional","menyatukan angkatan bersenjata","menutup perdagangan luar kawasan"],a:0,ex:"MEA (2015): pasar dan basis produksi tunggal, arus barang-jasa-investasi bebas; bukan mata uang tunggal atau penyatuan militer."},
{id:"TWK-2139",q:"Prinsip utama ASEAN dalam menyelesaikan sengketa antaranggota adalah ....",opts:["musyawarah dan non-intervensi","intervensi militer","sanksi ekonomi","pemungutan suara mayoritas","arbirase PBB"],a:0,ex:"ASEAN Way: musyawarah-mufakat dan tidak campur tangan urusan dalam negeri; bukan intervensi atau sanksi."},
{id:"TWK-2140",q:"Wawasan Nusantara sebagai geopolitik Indonesia berarti ....",opts:["cara pandang bangsa terhadap diri dan lingkungannya","strategi perang wilayah","rencana ekspansi teritorial","doktrin pertahanan semata","peta wilayah administratif"],a:0,ex:"Geopolitik Wawasan Nusantara = cara pandang menyeluruh bangsa atas diri-lingkungannya; bukan strategi perang atau ekspansi."},
{id:"TWK-2141",q:"Wawasan Nusantara pada hakikatnya adalah ....",opts:["keutuhan nusantara dalam arti ideologi, politik, ekonomi, sosial budaya, dan hankam","keutuhan wilayah daratan saja","persatuan angkatan bersenjata","kesatuan bahasa nasional","kebulatan tekad militer"],a:0,ex:"Hakikatnya keutuhan nusantara seutuhnya (pancagatra); bukan sekadar wilayah darat atau militer."},
{id:"TWK-2142",q:"Implementasi Wawasan Nusantara di bidang politik adalah ....",opts:["menjunjung demokrasi dan hak asasi manusia","menutup kran demokrasi","sentralisasi kekuasaan mutlak","penghapusan partai politik","pembatasan kebebasan"],a:0,ex:"Wawasan Nusantara di politik = demokrasi, HAM, kedaulatan rakyat; bukan otoritarianisme."},
{id:"TWK-2143",q:"Kawasan perbatasan laut Indonesia di sebelah utara berbatasan dengan ....",opts:["Malaysia dan Singapura","Australia dan Timor Leste","Papua Nugini dan Australia","India dan Thailand","Vietnam dan Kamboja"],a:0,ex:"Utara: Malaysia-Singapura (Selat Malaka); selatan: Australia-Timor Leste; timur: PNG-Palau; barat: India-Thailand."},
{id:"TWK-2144",q:"Garis Wallace yang membagi kawasan fauna nusantara memisahkan fauna ....",opts:["Indonesia barat dan tengah","Indonesia tengah dan timur","Jawa dan Sumatra","Kalimantan dan Sulawesi","Papua dan Maluku"],a:0,ex:"Garis Wallace: barat (Asia) vs tengah (peralihan); Garis Weber: tengah vs timur (Australia)."},
{id:"TWK-2145",q:"Pulau terbesar yang seluruhnya merupakan wilayah Indonesia adalah ....",opts:["Kalimantan","Sumatra","Jawa","Sulawesi","Papua"],a:0,ex:"Kalimantan terbesar yang sepenuhnya wilayah RI; Papua lebih besar tetapi terbagi dengan PNG."},
{id:"TWK-2146",q:"Jumlah pulau di nusantara Indonesia sekitar ....",opts:["lebih dari 17.000 pulau","kurang dari 10.000 pulau","tepat 13.000 pulau","kurang dari 5.000 pulau","tepat 20.000 pulau"],a:0,ex:"Indonesia memiliki 16.771-17.504 pulau terdaftar (versi BIG/KKP); disebut negara kepulauan terbesar."},
{id:"TWK-2147",q:"Sumpah Palapa sebagai tekad mempersatukan nusantara berbunyi ....",opts:["tidak akan berhenti berpuasa sebelum menyatukan nusantara","akan menaklukkan seluruh dunia","tidak akan makan sebelum menang perang","akan membangun candi terbesar","tidak akan pulang sebelum kaya raya"],a:0,ex:"Sumpah Palapa Gajah Mada (1336): 'Sira Gajah Madepun... tan ayun amukti palapa' — tidak menikmati kesenangan sebelum Nusantara bersatu."},
{id:"TWK-2148",q:"Kitab Negarakertagama yang menggambarkan kejayaan nusantara dikarang oleh ....",opts:["Mpu Prapanca","Mpu Tantular","Mpu Kanwa","Empu Sedah","Mpu Panuluh"],a:0,ex:"Negarakertagama (1365) karya Mpu Prapanca era Hayam Wuruk; Sutasoma karya Mpu Tantular."},
{id:"TWK-2149",q:"Pengaturan semboyan Bhinneka Tunggal Ika tercantum dalam ....",opts:["UU No. 24 Tahun 2009","UU No. 32 Tahun 2004","UU No. 23 Tahun 2014","UU No. 12 Tahun 2011","UU No. 39 Tahun 1999"],a:0,ex:"UU 24/2009 (Bendera, Bahasa, Lambang Negara) mengatur semboyan; UUD 1945 Pasal 36A lambang negara."},
{id:"TWK-2150",q:"Semboyan 'NKRI harga mati' mengandung makna ....",opts:["keutuhan NKRI tidak dapat ditawar","NKRI boleh dinegosiasi","bentuk negara dapat diubah","daerah boleh memisahkan diri","kedaulatan dapat dibagi"],a:0,ex:"NKRI harga mati = komitmen mutlak menjaga keutuhan; bukan negosiasi, federalisme, atau separatisme."},
{id:"TWK-2151",q:"Unsur pembentuk NKRI menurut teori konvensional adalah ....",opts:["rakyat, wilayah, dan pemerintah yang berdaulat","rakyat, tentara, dan polisi","wilayah, kekayaan, dan tentara","pemerintah, parlemen, dan pengadilan","rakyat, bahasa, dan budaya"],a:0,ex:"Unsur konstitutif negara: rakyat, wilayah, pemerintah berdaulat (ditambah pengakuan negara lain sebagai deklaratif); tentara-polisi bukan unsur."},
{id:"TWK-2152",q:"Sifat kedaulatan NKRI adalah ....",opts:["asli, permanen, tunggal, dan tidak terbatas","berasal dari negara lain","sementara dan dapat dicabut","terbagi antara pusat dan daerah","terbatas pada urusan dalam negeri"],a:0,ex:"Sifat kedaulatan: asli (tidak pemberian), permanen, tunggal, tidak terbatas; bukan pemberian, sementara, atau terbagi."},
{id:"TWK-2153",q:"Kedaulatan ke dalam pada NKRI berarti ....",opts:["kekuasaan tertinggi mengatur dan menjalankan pemerintahan negara","kekuasaan mengatur negara lain","kewajiban tunduk pada negara asing","pembagian kekuasaan dengan daerah","penyerahan sebagian kedaulatan"],a:0,ex:"Kedaulatan ke dalam = kekuasaan tertinggi ke dalam negeri; ke luar = bebas berhubungan dengan negara lain tanpa campur tangan."},
{id:"TWK-2154",q:"Contoh kedaulatan ke luar NKRI adalah ....",opts:["menjalin hubungan diplomatik dengan negara lain","menetapkan undang-undang","mengadili warga negara","menarik pajak","mengatur lalu lintas"],a:0,ex:"Kedaulatan ke luar = hubungan antarnegara (diplomasi); UU, peradilan, pajak, lalu lintas = kedaulatan ke dalam."},
{id:"TWK-2155",q:"Tujuan nasional dalam wawasan kebangsaan Indonesia adalah ....",opts:["melindungi segenap bangsa dan memajukan kesejahteraan umum","memperluas wilayah ke negara tetangga","menjadi negara adikuasa","menguasai perekonomian dunia","menyaingi negara maju"],a:0,ex:"Tujuan nasional (Pembukaan alinea 4): melindungi bangsa, mencerdaskan, kesejahteraan umum, perdamaian dunia; bukan ekspansi atau adikuasa."},
{id:"TWK-2156",q:"Fungsi NKRI sebagai negara adalah ....",opts:["melindungi, menyejahterakan, dan mencerdaskan rakyat","mengumpulkan pajak sebanyak-banyaknya","memperbanyak pegawai negeri","membangun istana negara","mengadakan upacara kenegaraan"],a:0,ex:"Fungsi negara: proteksi, kesejahteraan, pencerdasan; pajak, pegawai, dan upacara adalah instrumen, bukan fungsi."},
{id:"TWK-2157",q:"Ciri negara hukum NKRI adalah ....",opts:["adanya supremasi hukum","kekuasaan penguasa mutlak","hukum hanya untuk rakyat kecil","putusan pengadilan dapat diabaikan","hukum dibuat sekehendak penguasa"],a:0,ex:"Negara hukum: supremasi hukum, persamaan di depan hukum, due process; bukan kekuasaan mutlak atau hukum tebang pilih."},
{id:"TWK-2158",q:"Demokrasi yang dianut NKRI adalah demokrasi ....",opts:["yang berlandaskan musyawarah untuk mufakat","liberal ala Barat","komunis ala Timur","langsung tanpa perwakilan","terpimpin mutlak"],a:0,ex:"Demokrasi Indonesia berlandaskan musyawarah-mufakat (sila 4); bukan liberalisme, komunisme, atau terpimpin mutlak."},
{id:"TWK-2159",q:"Kedaulatan rakyat dalam NKRI diwujudkan melalui ....",opts:["pemilihan umum yang demokratis","keputusan sepihak penguasa","musyawarah tertutup elite","penunjukan langsung","undian"],a:0,ex:"Kedaulatan rakyat diwujudkan lewat pemilu demokratis dan lembaga perwakilan; bukan keputusan sepihak atau penunjukan."},
{id:"TWK-2160",q:"Sistem pemerintahan yang dianut NKRI adalah ....",opts:["presidensial","parlementer","semi presidensial","monarki konstitusional","direktorial"],a:0,ex:"Indonesia menganut presidensial: presiden kepala negara-pemerintahan; bukan parlementer (PM) atau monarki."},
{id:"TWK-2161",q:"Ciri sistem presidensial di NKRI adalah ....",opts:["presiden sebagai kepala negara sekaligus kepala pemerintahan","presiden bertanggung jawab kepada parlemen","menteri diangkat oleh parlemen","presiden dipilih oleh MPR","kabinet dapat dijatuhkan parlemen"],a:0,ex:"Presidensial: presiden kepala negara-pemerintahan, tidak bertanggung jawab ke parlemen, menteri pembantu presiden."},
{id:"TWK-2162",q:"Ibu kota negara Indonesia dalam proses pemindahan ke Nusantara terletak di ....",opts:["Nusantara, Kalimantan Timur","Yogyakarta, DIY","Surabaya, Jawa Timur","Makassar, Sulawesi Selatan","Medan, Sumatra Utara"],a:0,ex:"IKN Nusantara di Penajam Paser Utara-Kutai Kartanegara, Kalimantan Timur (UU 3/2022)."},
{id:"TWK-2163",q:"Alasan pemindahan ibu kota ke Nusantara adalah ....",opts:["pemerataan pembangunan dan mengurangi beban Jakarta","Jakarta tenggelam seluruhnya","meniru negara lain","keinginan presiden semata","menghemat anggaran negara"],a:0,ex:"Alasan: pemerataan, mengurangi beban Jakarta (banjir, macet, penurunan tanah), dan visi Indonesia-sentris."},
{id:"TWK-2164",q:"Wawasan kebangsaan penting bagi generasi muda karena ....",opts:["menangkal pengaruh negatif globalisasi","menghafal sejarah perjuangan","menambah beban pelajaran","mengganti pelajaran lain","agar lulus ujian"],a:0,ex:"Wawasan kebangsaan membentengi generasi dari pengaruh negatif global; bukan sekadar hafalan atau beban pelajaran."},
{id:"TWK-2165",q:"Pulau Weh terletak di provinsi ....",opts:["Aceh","Sumatra Utara","Riau","Jawa Barat","Bali"],a:0,ex:"Pulau Weh (Sabang) di Aceh, titik barat Indonesia; bukan provinsi lain."},
{id:"TWK-2166",q:"Pulau Rote terletak di provinsi ....",opts:["Nusa Tenggara Timur","Nusa Tenggara Barat","Maluku","Bali","Sulawesi Selatan"],a:0,ex:"Rote di NTT, titik selatan Indonesia; bukan NTB, Maluku, atau Bali."},
{id:"TWK-2167",q:"Titik paling utara wilayah Indonesia berada di pulau ....",opts:["Pulau Miangas","Pulau Weh","Pulau Rote","Pulau Sebatik","Pulau Natuna"],a:0,ex:"Miangas (Sulut) titik utara; Weh barat, Rote selatan, Sebatik perbatasan Malaysia-Kalimantan."},
{id:"TWK-2168",q:"Kata baku dari 'aktifitas' adalah ....",opts:["aktivitas","aktifitas","aktipitas","aktivites","aktivity"],a:0,ex:"Bentuk baku: aktivitas; 'aktifitas' tidak baku."},
{id:"TWK-2169",q:"Kata baku dari 'atlit' adalah ....",opts:["atlet","atlit","athlet","atletik","atlitik"],a:0,ex:"Bentuk baku: atlet; 'atlit' tidak baku (atletik = cabang olahraga)."},
{id:"TWK-2170",q:"Kata baku dari 'bis' untuk kendaraan umum adalah ....",opts:["bus","bis","bass","biss","buus"],a:0,ex:"Bentuk baku: bus; 'bis' tidak baku."},
{id:"TWK-2171",q:"Kata baku dari 'cinderamata' adalah ....",opts:["cenderamata","cinderamata","cendramata","cinderamta","cendramatta"],a:0,ex:"Bentuk baku: cenderamata; 'cinderamata' tidak baku."},
{id:"TWK-2172",q:"Kata baku dari 'diagnosa' adalah ....",opts:["diagnosis","diagnosa","diaggnosa","diagnossa","diagnose"],a:0,ex:"Bentuk baku: diagnosis; 'mendiagnosis' kata kerja."},
{id:"TWK-2173",q:"Bentuk kata baku dari 'ekstrim' adalah ....",opts:["ekstrem","ekstrim","extrim","ekstreem","ekstrimm"],a:0,ex:"Bentuk baku: ekstrem; 'ekstrim' tidak baku."},
{id:"TWK-2174",q:"Kata baku dari 'frekwensi' adalah ....",opts:["frekuensi","frekwensi","frequensi","frekuensy","frekwensy"],a:0,ex:"Bentuk baku: frekuensi; 'frekwensi' tidak baku."},
{id:"TWK-2175",q:"Kata baku dari 'komplit' adalah ....",opts:["komplet","komplit","complete","kompleet","komplitt"],a:0,ex:"Bentuk baku: komplet; 'komplit' tidak baku."},
{id:"TWK-2176",q:"Kata baku dari 'kwalitas' adalah ....",opts:["kualitas","kwalitas","quality","kualites","kwalites"],a:0,ex:"Bentuk baku: kualitas; 'kwalitas' tidak baku."},
{id:"TWK-2177",q:"Kata baku dari 'methode' adalah ....",opts:["metode","methode","methoda","metoda","mettode"],a:0,ex:"Bentuk baku: metode; 'metoda' juga tidak baku."},
{id:"TWK-2178",q:"Kata baku dari 'pebruari' adalah ....",opts:["Februari","pebruari","februari","Pebruari","febuari"],a:0,ex:"Nama bulan huruf awal kapital dan bentuk baku: Februari; 'Pebruari' tidak baku."},
{id:"TWK-2179",q:"Bentuk kata baku dari 'tehnik' adalah ....",opts:["teknik","tehnik","technik","tekhnik","tekniq"],a:0,ex:"Bentuk baku: teknik; 'tehnik' tidak baku."},
{id:"TWK-2180",q:"Kata baku dari 'jaman' adalah ....",opts:["zaman","jaman","saman","djaman","zamaan"],a:0,ex:"Bentuk baku: zaman; 'jaman' tidak baku."},
{id:"TWK-2181",q:"Kalimat majemuk adalah kalimat yang ....",opts:["memiliki lebih dari satu klausa","hanya memiliki satu klausa","tidak memiliki predikat","terdiri atas satu kata","tanpa tanda baca"],a:0,ex:"Kalimat majemuk = dua klausa atau lebih; satu klausa = kalimat tunggal."},
{id:"TWK-2182",q:"Klausa dalam kalimat adalah ....",opts:["satuan gramatikal yang memiliki predikat","kata yang berdiri sendiri","tanda baca dalam kalimat","huruf awal kalimat","akhir kalimat"],a:0,ex:"Klausa = kelompok kata berpola S-P (minimal berpredikat), berpotensi menjadi kalimat."},
{id:"TWK-2183",q:"Subjek kalimat 'Anak itu membaca buku' adalah ....",opts:["Anak itu","membaca","buku","Anak itu membaca","membaca buku"],a:0,ex:"Subjek = 'Anak itu'; predikat 'membaca', objek 'buku'."},
{id:"TWK-2184",q:"Predikat kalimat 'Mereka bermain bola' adalah ....",opts:["bermain","Mereka","bola","Mereka bermain","bermain bola"],a:0,ex:"Predikat = 'bermain'; subjek 'Mereka', objek 'bola'."},
{id:"TWK-2185",q:"Tanda baca hubung digunakan untuk ....",opts:["menyambung unsur kata ulang dan rentang","mengakhiri kalimat","mengapit dialog","memisahkan kalimat","menyatakan pertanyaan"],a:0,ex:"Tanda hubung (-): kata ulang (anak-anak), rentang (1945-1950), 'ke-21'; akhir kalimat memakai titik."},
{id:"TWK-2186",q:"Fungsi tanda baca petik adalah ....",opts:["mengapit petikan langsung atau dialog","mengakhiri kalimat tanya","memisahkan unsur pemerincian","menyambung kata ulang","menandai singkatan"],a:0,ex:"Tanda petik (\"...\"): petikan langsung, judul, istilah; bukan akhir kalimat atau pemerincian."},
{id:"TWK-2187",q:"Penulisan mata uang rupiah yang tepat adalah ....",opts:["Rp5.000,00","Rp 5.000","Rp. 5.000,00","RP5.000","Rp5000"],a:0,ex:"Penulisan baku: Rp5.000,00 (tanpa spasi setelah Rp, titik ribuan, koma desimal); 'RP' dan spasi salah."},
{id:"TWK-2188",q:"Penulisan persen yang tepat adalah ....",opts:["20%","20 %","20 persen %","%20","20persen"],a:0,ex:"Lambang % dirangkai tanpa spasi: 20%; bentuk kata '20 persen' juga baku."},
{id:"TWK-2189",q:"Penulisan singkatan gelar 'Sarjana Hukum' yang tepat adalah ....",opts:["S.H.","SH","S.H","S.H..","Sh"],a:0,ex:"Singkatan gelar memakai titik tiap unsur: S.H.; tanpa titik atau titik ganda tidak baku."},
{id:"TWK-2190",q:"Imbuhan 'ber-' pada kata 'main' menjadi ....",opts:["bermain","bermain-main","memain","dimain","pemain"],a:0,ex:"ber- + main → bermain (luluh? tidak, langsung rangkai); 'pemain' memakai pe-."},
{id:"TWK-2191",q:"Kata 'menyapu' berasal dari kata dasar 'sapu' yang mendapat imbuhan ....",opts:["me-","pe-","ber-","di-","se-"],a:0,ex:"menyapu = me- + sapu (s luluh menjadi ny); pe- menghasilkan penyapu, ber-/di-/se- tidak tepat."},
{id:"TWK-2192",q:"Imbuhan 'ke-an' pada kata 'tua' menjadi ....",opts:["ketuaan","ketuan","ketaan","mentua","tertua"],a:0,ex:"ke- + tua + -an → ketuaan; 'tertua' memakai ter-."},
{id:"TWK-2193",q:"Penulisan kata ulang 'rumah-rumah' bermakna ....",opts:["jamak","tunggal","kecil","besar","baru"],a:0,ex:"Pengulangan bermakna jamak/banyak: rumah-rumah = banyak rumah."},
{id:"TWK-2194",q:"Kata serapan 'check' dalam bahasa Indonesia adalah ....",opts:["cek","check","chek","cekk","cheque"],a:0,ex:"Serapan baku: cek; 'check' bentuk asing."},
{id:"TWK-2195",q:"Kata serapan 'file' dalam bahasa Indonesia adalah ....",opts:["berkas","file","fail","berkas file","pile"],a:0,ex:"Padanan baku 'file' adalah berkas; 'fail' tidak baku."},
{id:"TWK-2196",q:"Ciri ejaan Van Ophuijsen adalah penggunaan ....",opts:["'oe' untuk bunyi 'u'","'u' untuk bunyi 'oe'","'e' untuk bunyi 'o'","'j' untuk bunyi 'y'","'x' untuk bunyi 'ks'"],a:0,ex:"Van Ophuijsen (1901): oe=u, j=y, ch=kh, tj=c; EYD 1972 mengganti oe→u, tj→c, dj→j."},
{id:"TWK-2197",q:"Paragraf yang baik memiliki ....",opts:["kesatuan, kepaduan, dan ketuntasan","kalimat yang panjang-panjang","banyak gagasan utama","tanpa kalimat penjelas","huruf kapital semua"],a:0,ex:"Syarat paragraf baik: kesatuan (satu gagasan), kepaduan (kohesi), ketuntasan (pengembangan cukup)."},
{id:"TWK-2198",q:"Kohesi paragraf berarti ....",opts:["kepadian hubungan antar kalimat","banyaknya kalimat","panjangnya paragraf","keindahan bahasa","kecepatan membaca"],a:0,ex:"Kohesi = kepaduan/keterkaitan antar kalimat lewat konjungsi, repetisi, substitusi; koherensi = keterpaduan makna."},
{id:"TWK-2199",q:"Gagasan utama paragraf disebut ....",opts:["gagasan pokok","gagasan tambahan","gagasan sampingan","gagasan kecil","gagasan baru"],a:0,ex:"Gagasan utama = gagasan pokok/ide pokok; dikembangkan oleh gagasan penjelas."},
{id:"TWK-2200",q:"Kalimat penjelas berfungsi untuk ....",opts:["menguraikan gagasan utama paragraf","menggantikan gagasan utama","meniadakan gagasan utama","mengulang judul karangan","menutup paragraf"],a:0,ex:"Kalimat penjelas menguraikan/mendukung gagasan utama; bukan menggantikan atau meniadakannya."},
];
